import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        names = sorted(packages, reverse=(name_order == "descending"))
        best_score = None
        best = None

        requirements = {}
        for name, bounds in data["roots"].items():
            requirements.setdefault(name, []).append(tuple(bounds))

        def acyclic(edges):
            state = {}

            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                if any(not visit(other) for other in edges.get(name, ())):
                    return False
                state[name] = 2
                return True

            return all(visit(name) for name in edges)

        def search(chosen, reqs, edges):
            nonlocal best, best_score
            pending = [name for name in reqs if name not in chosen]
            if not pending:
                if not acyclic(edges):
                    return
                score = tuple(chosen.get(name, -1) for name in names)
                if (best_score is None or
                        (score > best_score if preference == "maximum" else score < best_score)):
                    best_score = score
                    best = dict(chosen)
                return

            name = pending[0]
            constraints = reqs[name]
            low = max(lo for lo, _ in constraints)
            high = min(hi for _, hi in constraints)
            rows = [row for row in packages.get(name, [])
                    if low <= row["version"] <= high
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            rows.sort(key=lambda row: row["version"], reverse=(preference == "maximum"))

            for row in rows:
                version = row["version"]
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_reqs = {key: list(value) for key, value in reqs.items()}
                next_edges = {key: list(value) for key, value in edges.items()}
                next_edges.setdefault(name, [])
                valid = True
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    bound = (dep["min"], dep["max"])
                    next_reqs.setdefault(target, []).append(bound)
                    next_edges[name].append(target)
                    if target in next_chosen:
                        chosen_version = next_chosen[target]
                        if not (bound[0] <= chosen_version <= bound[1]):
                            valid = False
                            break
                if valid:
                    search(next_chosen, next_reqs, next_edges)

        search({}, requirements, {})
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}

    return solve


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (2 * numerator + denominator) // (2 * denominator)
    return numerator // denominator


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        tax = _round(raw * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(options, k):
        ids = [job["id"] for job in subset]
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts[group] <= high
               for group, (low, high) in quotas.items()):
            continue
        if any(counts[group] != 0 and group not in quotas
               for group in counts):
            continue

        active_ends = []
        valid = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue

        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    start_mask = bit_for.get(start_node, 0)
    start_time = data["start"]
    initial = (start_node, start_mask, data["coupons"])
    best = {initial: start_time}
    queue = [(start_time, start_node, start_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if best.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_remaining))

    return {"arrival": None}


